"""Manuell belegte Ergänzungen aus gelesenen Studienseiten und Curriculumgrafiken."""
import json
from research_hs import ROOT

cs=json.loads((ROOT/'programs.json').read_text())
extra={}
def put(part, **values):
    c=next((c for c in cs if c['title'].replace('\xad','').startswith(part)),None)
    if c is None:c=next(c for c in cs if part in c['title'])
    extra.setdefault(str(c['uid']),{}).update(values)
    return c
def row(phase, modules, kind='Veröffentlichte Module', track='Grundverlauf'):
    return [phase,track,kind,modules.split('; ')]
def src(c):return c['detail_links'][0]['url']

